<?php get_header(); $archive_url = home_search_archive_url(); ?>
<div class="wrap"><div class="page-intro"><span class="eyebrow">Discover your place</span><h1>Explore our properties.</h1><p>Find the right space for your next chapter. Refine the collection or explore each address on the map.</p></div>
<form id="property-filters" class="filter-panel filter-grid" action="<?php echo esc_url($archive_url); ?>" method="get"><div class="field"><label for="filter-location">Location</label><input id="filter-location" name="location" placeholder="City or neighborhood" value="<?php echo esc_attr(sanitize_text_field(home_search_query_value('location'))); ?>"></div><div class="field"><label for="filter-type">Property type</label><select id="filter-type" name="type"><option value="">All types</option><?php foreach (home_search_property_types() as $term) : ?><option value="<?php echo esc_attr($term->slug); ?>" <?php selected(sanitize_title(home_search_query_value('type')), $term->slug); ?>><?php echo esc_html($term->name); ?></option><?php endforeach; ?></select></div><div class="field"><label for="filter-min">Min price</label><input id="filter-min" name="min_price" type="number" min="0" step="100000" placeholder="₱ Any" value="<?php echo esc_attr(absint(home_search_query_value('min_price')) ?: ''); ?>"></div><div class="field"><label for="filter-max">Max price</label><input id="filter-max" name="max_price" type="number" min="0" step="100000" placeholder="₱ Any" value="<?php echo esc_attr(absint(home_search_query_value('max_price')) ?: ''); ?>"></div><div class="field"><label for="filter-beds">Bedrooms</label><select id="filter-beds" name="bedrooms"><option value="">Any</option><?php for ($i = 1; $i <= 5; $i++) : ?><option value="<?php echo $i; ?>" <?php selected(absint(home_search_query_value('bedrooms')), $i); ?>><?php echo $i; ?>+</option><?php endfor; ?></select></div><button class="button button-accent" type="submit">Apply filters</button></form>
<div class="results-bar"><p id="result-count" role="status"><?php echo esc_html(sprintf(_n('%d home found', '%d homes found', $wp_query->found_posts, 'home-search'), $wp_query->found_posts)); ?></p><div class="view-switch" role="group" aria-label="Result view"><button type="button" data-view="list" aria-pressed="true">List</button><button type="button" data-view="map" aria-pressed="false">Map</button></div></div>
<div id="results-layout" class="results-layout"><div><div id="property-results" class="card-grid"><?php if (have_posts()) : while (have_posts()) : the_post(); get_template_part('template-parts/property-card', null, ['id' => get_the_ID()]); endwhile; else : ?><div class="empty-state"><h3>No homes found.</h3><p>Try a different location or a wider price range.</p></div><?php endif; ?></div><button id="load-more" class="button button-outline load-more" type="button" hidden>Load more homes</button><div id="server-pagination"><?php the_posts_pagination(); ?></div></div><div id="property-map" class="map-panel" aria-label="Map of matching properties" hidden></div></div>
